for root, _, files in os.walk('/mnt/Storage/Projects/WebsitePro/src'):
    for file in files:
        if file.endswith('.svelte') or file.endswith('.ts'):
            filepath = os.path.join(root, file)
            with open(filepath, 'r') as f:
                content = f.read()
            original = content
            if 'levels.ts' in file:
                 content = re.sub(r'[📦🔒💀🔑🕸🗄🗑🌐🖴☠👑⛔📄]+', '[X]', content)
            else:
                 for emoji, svg in emoji_svg_map.items():
                    content = content.replace(emoji, svg)
            if content != original:
                with open(filepath, 'w') as f:
                    f.write(content)
                print(f"Replaced emojis in {filepath}")
